-- Data quality: for every visit, how far did it get through the pipeline —
-- visit only, visit + proposal, or all the way to an invoice. A package on
-- its own isn't a stage: every non-invoiced package also has a proposal, so
-- nothing ever actually stops there. Grain is one row per visit; nb_proposals
-- and nb_invoices are the totals generated by the visits in that stage, not
-- a second row count, so a visit with several proposals/invoices counts once
-- toward nb_visits but contributes its full total to the other two columns.
-- Run with: dbt show --select dq_sales_funnel_stopped_at --limit 100
with visits as (

    select visit_id
    from {{ ref('int_visits') }}

),

packages as (

    select package_id, visit_id, proposal_id
    from {{ ref('int_packages') }}

),

invoiced_packages as (

    select distinct p.package_id, cid.facture_id
    from {{ ref('int_packages') }} as p
    join {{ ref('int_package_details') }} as pd using (package_id)
    join {{ ref('int_factures_details') }} as cid using (package_detail_id)

),

visit_rollup as (

    select
        v.visit_id,
        count(distinct pk.proposal_id) as nb_proposals,
        count(distinct ip.package_id) as nb_invoiced_packages,
        count(distinct ip.facture_id) as nb_invoices

    from visits as v
    left join packages as pk on pk.visit_id = v.visit_id
    left join invoiced_packages as ip on ip.package_id = pk.package_id
    group by v.visit_id

)

select
    case
        when nb_invoiced_packages > 0 then '3 - invoiced'
        when nb_proposals > 0 then '2 - visit + proposal'
        else '1 - visit only'
    end as funnel_stage,
    count(*) as nb_visits,
    sum(nb_proposals) as nb_proposals,
    sum(nb_invoices) as nb_invoices

from visit_rollup
group by funnel_stage
order by funnel_stage
